// Advanced Lead Classification System
const headers = $input.item.json.payload?.headers || [];
const subject = headers.find(h => h.name === 'Subject')?.value || '';
const from = headers.find(h => h.name === 'From')?.value || '';
const body = $input.item.json.snippet || '';
const fullContent = (subject + ' ' + body).toLowerCase();

// High-value keywords with weighted scoring
const keywords = {
  'drywall': 15,
  'basement': 20,
  'renovation': 18,
  'commercial': 25,
  'apartment': 22,
  'urgent': 30,
  'asap': 25,
  'quote': 12,
  'estimate': 12,
  'contractor': 10,
  'repair': 8,
  'installation': 15,
  'finishing': 12,
  'multi-unit': 30,
  'building': 20,
  'budget': 10,
  'timeline': 8
};

// Calculate lead score
let leadScore = 0;
let foundKeywords = [];

Object.entries(keywords).forEach(([keyword, points]) => {
  if (fullContent.includes(keyword)) {
    leadScore += points;
    foundKeywords.push(keyword);
  }
});

// Project size indicators
const sizeIndicators = {
  'sq ft': 15,
  'square feet': 15,
  'rooms': 10,
  'floor': 12,
  'house': 15,
  'condo': 12,
  'office': 18
};

Object.entries(sizeIndicators).forEach(([indicator, points]) => {
  if (fullContent.includes(indicator)) {
    leadScore += points;
  }
});

// Determine lead priority
let priority = 'low';
let action = 'log';

if (leadScore >= 40) {
  priority = 'urgent';
  action = 'immediate_sms';
} else if (leadScore >= 25) {
  priority = 'high';
  action = 'sms';
} else if (leadScore >= 10) {
  priority = 'medium';
  action = 'email_alert';
}

// Extract contact info
const phoneRegex = /\b\d{3}[-.]?\d{3}[-.]?\d{4}\b/;
const phoneMatch = fullContent.match(phoneRegex);

return {
  json: {
    timestamp: new Date().toISOString(),
    from: from,
    subject: subject,
    body: body.substring(0, 300),
    leadScore: leadScore,
    priority: priority,
    action: action,
    keywords: foundKeywords.join(', '),
    phone: phoneMatch ? phoneMatch[0] : null,
    estimatedValue: leadScore >= 30 ? '$1500+' : leadScore >= 15 ? '$800+' : '$400+',
    urgencyLevel: fullContent.includes('urgent') || fullContent.includes('asap') ? 'HIGH' : 'NORMAL'
  }
};

